// Basement sump controller.
// Ultrasonic level proxy as linear voltage on A1, pump contactor on D7,
// silence button on D4 (active LOW, pull-up).

const uint8_t LEVEL_PIN = A1;
const uint8_t PUMP_PIN = 7;
const uint8_t SILENCE_PIN = 4;

const float START_CM = 45.0f;
const float STOP_CM = 30.0f;
const float MV_PER_CM = 10.0f;
const unsigned long POLL_MS = 40;
const unsigned long LOG_MS = 800;
const unsigned long SILENCE_DEBOUNCE_MS = 50;

bool pumpOn = false;
bool silenceLatched = false;
unsigned long lastPoll = 0;
unsigned long lastLog = 0;
unsigned long lastPumpToggle = 0;
float levelCm = 0.0f;

float sampleLevelCm()
{
    int adc = analogRead(LEVEL_PIN);
    float mv = adc * (5000.0f / 1023.0f);
    return mv / MV_PER_CM;
}

void setPump(bool on)
{
    if (on != pumpOn && (millis() - lastPumpToggle >= 2500)) {
        pumpOn = on;
        digitalWrite(PUMP_PIN, on ? HIGH : LOW);
        lastPumpToggle = millis();
    }
}

void emitLog()
{
    Serial.print("sump cm=");
    Serial.print(levelCm, 1);
    Serial.print(" pump=");
    Serial.print(pumpOn ? 1 : 0);
    Serial.print(" mute=");
    Serial.println(silenceLatched ? 1 : 0);
}

void setup()
{
    pinMode(PUMP_PIN, OUTPUT);
    pinMode(SILENCE_PIN, INPUT_PULLUP);
    digitalWrite(PUMP_PIN, LOW);
    Serial.begin(9600);
    lastPoll = millis();
    lastLog = millis();
}

void loop()
{
    unsigned long t = millis();

    static unsigned long lastSilenceCheck = 0;
    if (t - lastSilenceCheck >= SILENCE_DEBOUNCE_MS) {
        lastSilenceCheck = t;
        if (digitalRead(SILENCE_PIN) == LOW)
        {
            silenceLatched = true;
            setPump(false);
        }
    }

    if (t - lastPoll >= POLL_MS)
    {
        lastPoll = t;
        levelCm = sampleLevelCm();

        if (!silenceLatched)
        {
            // Run whenever depth crosses the start mark.
            if (levelCm >= START_CM)
            {
                setPump(true);
            }
            else if (levelCm <= STOP_CM)
            {
                setPump(false);
            }
        }
    }

    if (t - lastLog >= LOG_MS)
    {
        lastLog = t;
        emitLog();
    }
}

// Walk-in cooler compressor controller (known-good build).
// Cabinet probe on A3 (10 mV/°C), compressor on D7, service switch on D4.

const int TEMP_PIN = A3;
const int COMP_PIN = 7;
const int SERVICE_PIN = 4;
const float COOL_ON_C = 8.0f;
const float COOL_OFF_C = 4.0f;
const float FAULT_LOW_C = 0.0f;
const float FAULT_HIGH_C = 60.0f;
const float MV_PER_C = 10.0f;
const unsigned long TICK_MS = 50;
const unsigned long STATUS_MS = 1000;
const int HOLD_N = 3;

bool cooling = false;
int onHold = 0;
int offHold = 0;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
float tempC = 0.0f;

float readTempC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void setCompressor(bool on)
{
    cooling = on;
    digitalWrite(COMP_PIN, on ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("cooler: ");
    Serial.print(tempC, 1);
    Serial.print(" C comp=");
    Serial.println(cooling ? "ON" : "OFF");
}

void setup()
{
    pinMode(COMP_PIN, OUTPUT);
    pinMode(SERVICE_PIN, INPUT_PULLUP);
    setCompressor(false);
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        tempC = readTempC();
        bool service = (digitalRead(SERVICE_PIN) == LOW);
        bool fault = (tempC < FAULT_LOW_C) || (tempC > FAULT_HIGH_C);

        if (service || fault)
        {
            onHold = 0;
            offHold = 0;
            setCompressor(false);
        }
        else
        {
            if (tempC >= COOL_ON_C)
            {
                onHold++;
            }
            else
            {
                onHold = 0;
            }

            if (tempC <= COOL_OFF_C)
            {
                offHold++;
            }
            else
            {
                offHold = 0;
            }

            if (onHold >= HOLD_N)
            {
                setCompressor(true);
            }
            else if (offHold >= HOLD_N)
            {
                setCompressor(false);
            }
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Greenhouse nutrient drip pulse scheduler.
// Pulse driver on D8, pause button on D4 (pull-up).

const int DRIP_PIN = 8;
const int PAUSE_PIN = 4;
const unsigned long PERIOD_MS = 800;
const unsigned long PULSE_MS = 50;
const unsigned long LOG_MS = 1600;

uint32_t nextDue = 0;
unsigned long pulseUntil = 0;
unsigned long lastLog = 0;
unsigned long dripCount = 0;
bool pulsing = false;
bool paused = false;

void dripHigh()
{
    digitalWrite(DRIP_PIN, HIGH);
}

void dripLow()
{
    digitalWrite(DRIP_PIN, LOW);
}

void startPulse(unsigned long now)
{
    pulsing = true;
    pulseUntil = now + PULSE_MS;
    dripHigh();
    dripCount++;
    Serial.println("drip");
}

void endPulse()
{
    pulsing = false;
    dripLow();
}

void printLog()
{
    Serial.print("drip n=");
    Serial.print(dripCount);
    Serial.print(" pause=");
    Serial.println(paused ? 1 : 0);
}

void setup()
{
    pinMode(DRIP_PIN, OUTPUT);
    pinMode(PAUSE_PIN, INPUT_PULLUP);
    dripLow();
    Serial.begin(9600);
    nextDue = millis() + PERIOD_MS;
    lastLog = millis();
}

void loop()
{
    unsigned long now = millis();
    paused = (digitalRead(PAUSE_PIN) == LOW);

    if (pulsing && (long)(now - pulseUntil) >= 0)
    {
        endPulse();
    }

    if (!paused && !pulsing && now >= nextDue)
    {
        nextDue = now + PERIOD_MS;
        startPulse(now);
    }

    if (paused)
    {
        nextDue = now + PERIOD_MS;
    }

    if (now - lastLog >= LOG_MS)
    {
        lastLog = now;
        printLog();
    }
}

// Foyer wall switch: one pushbutton toggles a lamp channel.
// Button D5 to ground (pull-up), lamp driver D11, status over serial.

const int SWITCH_PIN = 5;
const int LAMP_PIN = 11;
const unsigned long STATUS_EVERY_MS = 1500;
const unsigned long DEBOUNCE_MS = 40;

bool lampLit = false;
int previousRaw = HIGH;
unsigned long lastStatusAt = 0;
unsigned long pressEvents = 0;
unsigned long bootMs = 0;
unsigned long lastDebounceTime = 0;

void driveLamp(bool on)
{
    lampLit = on;
    digitalWrite(LAMP_PIN, on ? HIGH : LOW);
}

void flipLamp()
{
    driveLamp(!lampLit);
    pressEvents++;
}

bool isPressedEdge(int previous, int current)
{
    return previous == HIGH && current == LOW;
}

void reportLamp()
{
    Serial.print("foyer lamp=");
    Serial.println(lampLit ? "ON" : "OFF");
}

void setup()
{
    pinMode(SWITCH_PIN, INPUT_PULLUP);
    pinMode(LAMP_PIN, OUTPUT);
    driveLamp(false);
    Serial.begin(9600);
    previousRaw = digitalRead(SWITCH_PIN);
    lastStatusAt = millis();
    bootMs = millis();
}

void loop()
{
    int raw = digitalRead(SWITCH_PIN);
    unsigned long now = millis();

    if (raw != previousRaw) {
        lastDebounceTime = now;
    }

    if ((now - lastDebounceTime) > DEBOUNCE_MS) {
        if (isPressedEdge(previousRaw, raw))
        {
            flipLamp();
        }
    }
    previousRaw = raw;

    if (now - lastStatusAt >= STATUS_EVERY_MS)
    {
        lastStatusAt = now;
        reportLamp();
    }
}

// Packaging glue-dot solenoid driver.
// Trigger on D2 (pull-up), solenoid on D8, armed LED on D11.

const int TRIG_PIN = 2;
const int SOL_PIN = 8;
const int ARMED_PIN = 11;
const unsigned long PULSE_MS = 2500; // Corrected pulse duration
const unsigned long DEBOUNCE_MS = 25;
const unsigned long HB_MS = 500;

bool pulsing = false;
unsigned long pulseStart = 0;
int stableTrig = HIGH;
int lastTrig = HIGH;
unsigned long trigEdge = 0;
unsigned long lastHb = 0;
unsigned long dots = 0;

void solHigh()
{
    digitalWrite(SOL_PIN, HIGH);
}

void solLow()
{
    digitalWrite(SOL_PIN, LOW);
}

void setArmedLed(bool on)
{
    digitalWrite(ARMED_PIN, on ? HIGH : LOW);
}

void heartbeat()
{
    Serial.print("glue dots=");
    Serial.print(dots);
    Serial.print(" busy=");
    Serial.println(pulsing ? 1 : 0);
}

void setup()
{
    pinMode(TRIG_PIN, INPUT_PULLUP);
    pinMode(SOL_PIN, OUTPUT);
    pinMode(ARMED_PIN, OUTPUT);
    solLow();
    setArmedLed(true);
    Serial.begin(9600);
    stableTrig = digitalRead(TRIG_PIN);
    lastTrig = stableTrig;
    lastHb = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(TRIG_PIN);

    if (raw != lastTrig)
    {
        trigEdge = now;
        lastTrig = raw;
    }

    if ((now - trigEdge) >= DEBOUNCE_MS && raw != stableTrig)
    {
        stableTrig = raw;
        if (stableTrig == LOW && !pulsing)
        {
            pulsing = true;
            pulseStart = now;
            dots++;
            solHigh();
            setArmedLed(false);
        }
    }

    if (pulsing && (now - pulseStart) >= PULSE_MS)
    {
        pulsing = false;
        solLow();
        setArmedLed(true);
    }

    if (now - lastHb >= HB_MS)
    {
        lastHb = now;
        heartbeat();
    }
}

// Greenhouse ridge-vent controller.
// Soil-air LM35 on A2, exhaust fan relay on D9, UART status.

const int SENSOR_PIN = A2;
const int FAN_PIN = 9;
const float OPEN_C = 28.0f;
const float CLOSE_C = 24.0f;
const float MV_PER_C = 10.0f;
const unsigned long TICK_MS = 50;
const unsigned long STATUS_MS = 1000;
const unsigned long FAN_STATE_CHANGE_WINDOW_MS = 5000;

bool fanOn = false;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
unsigned long lastFanChange = 0;
unsigned long sampleCount = 0;
float tempC = 0.0f;
float tempMin = 999.0f;
float tempMax = -999.0f;

float readTempC()
{
    int raw = analogRead(SENSOR_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void trackTemp(float c)
{
    if (c < tempMin)
    {
        tempMin = c;
    }
    if (c > tempMax)
    {
        tempMax = c;
    }
}

void setFan(bool on)
{
    fanOn = on;
    digitalWrite(FAN_PIN, on ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("gh: ");
    Serial.print(tempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        tempC = readTempC();
        sampleCount++;
        trackTemp(tempC);

        if (tempC < 5.0f || tempC > 100.0f)
        {
            if (!fanOn)
            {
                setFan(true);
                lastFanChange = now;
            }
        }
        else if (tempC >= OPEN_C)
        {
            if (!fanOn && (now - lastFanChange >= FAN_STATE_CHANGE_WINDOW_MS / 2))
            {
                setFan(true);
                lastFanChange = now;
            }
        }
        else if (tempC <= CLOSE_C)
        {
            if (fanOn && (now - lastFanChange >= FAN_STATE_CHANGE_WINDOW_MS / 2))
            {
                setFan(false);
                lastFanChange = now;
            }
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Potting-shed vent controller (known-good build).
// Air probe on A0, vent fan on D6, UART status.

const int TEMP_PIN = A0;
const int FAN_PIN = 6;
const float OPEN_C = 30.0f;
const float CLOSE_C = 26.0f;
const float FAULT_LOW_C = 5.0f;
const float FAULT_HIGH_C = 100.0f;
const float MV_PER_C = 10.0f;
const unsigned long TICK_MS = 50;
const unsigned long STATUS_MS = 1000;
const int HOLD_N = 4;
const int CLEAR_N = 8;

bool fanOn = false;
bool faultLatched = false;
int openHold = 0;
int closeHold = 0;
int faultHold = 0;
int clearHold = 0;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
unsigned long lastFanChange = 0;
int fanChangeCount = 0;
float tempC = 0.0f;

float readTempC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void setFan(bool on)
{
    fanOn = on;
    digitalWrite(FAN_PIN, on ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("shed: ");
    Serial.print(tempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        tempC = readTempC();

        bool outOfRange = (tempC < FAULT_LOW_C) || (tempC > FAULT_HIGH_C);
        if (outOfRange)
        {
            faultHold++;
            clearHold = 0;
            openHold = 0;
            closeHold = 0;
        }
        else
        {
            faultHold = 0;
            clearHold++;
            if (tempC >= OPEN_C)
            {
                openHold++;
            }
            else
            {
                openHold = 0;
            }
            if (tempC <= CLOSE_C)
            {
                closeHold++;
            }
            else
            {
                closeHold = 0;
            }
        }

        if (faultHold >= HOLD_N)
        {
            faultLatched = true;
        }
        if (faultLatched && clearHold >= CLEAR_N)
        {
            faultLatched = false;
        }

        if (faultLatched)
        {
            setFan(true);
            lastFanChange = now;
            fanChangeCount = 0;
        }
        else if (openHold >= HOLD_N && fanChangeCount < 2)
        {
            setFan(true);
            lastFanChange = now;
            fanChangeCount++;
        }
        else if (closeHold >= HOLD_N && fanChangeCount < 2)
        {
            setFan(false);
            lastFanChange = now;
            fanChangeCount++;
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }

    if (faultLatched && (now - lastFanChange >= 600))
    {
        setFan(true);
    }
}

// Shop hoist contactor with mushroom e-stop.
// E-stop on D3 (NC to ground via switch, pull-up), contactor on D5.
// Run request on D6 (pull-up).

const int ESTOP_PIN = 3;
const int CONTACTOR_PIN = 5;
const int RUN_PIN = 6;
const unsigned long SETTLE_MS = 30;
const unsigned long BEAT_MS = 1100;

int stableStop = HIGH;
int lastStop = HIGH;
unsigned long stopEdge = 0;
bool contactorOn = false;
unsigned long lastBeat = 0;
unsigned long tripCount = 0;

bool estopActive(int level)
{
    return level == HIGH;
}

void setContactor(bool on)
{
    contactorOn = on;
    digitalWrite(CONTACTOR_PIN, on ? HIGH : LOW);
}

void heartbeat()
{
    Serial.print("hoist run=");
    Serial.print(contactorOn ? 1 : 0);
    Serial.print(" trips=");
    Serial.println(tripCount);
}

void setup()
{
    pinMode(ESTOP_PIN, INPUT_PULLUP);
    pinMode(RUN_PIN, INPUT_PULLUP);
    pinMode(CONTACTOR_PIN, OUTPUT);
    setContactor(false);
    Serial.begin(9600);
    stableStop = digitalRead(ESTOP_PIN);
    lastStop = stableStop;
    lastBeat = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(ESTOP_PIN);

    if (raw != lastStop)
    {
        stopEdge = now;
        lastStop = raw;
    }

    if ((now - stopEdge) >= SETTLE_MS && raw != stableStop)
    {
        if (estopActive(raw) && !estopActive(stableStop))
        {
            tripCount++;
        }
        stableStop = raw;
    }

    bool stopped = estopActive(stableStop);
    bool runReq = (digitalRead(RUN_PIN) == LOW);

    if (stopped)
    {
        setContactor(false);
    }
    else if (runReq)
    {
        setContactor(true);
    }
    else
    {
        setContactor(false);
    }

    if (now - lastBeat >= BEAT_MS)
    {
        lastBeat = now;
        heartbeat();
    }
}

