// Safe-deposit vault lock latch (known-good build).
// Request button on D2, door-closed sense on D3 (both pull-up), lock solenoid on D9.

const int REQ_PIN = 2;
const int DOOR_PIN = 3;
const int LOCK_PIN = 9;
const unsigned long DEBOUNCE_MS = 35;
const unsigned long STATUS_MS = 1000;
const unsigned long UNLOCK_DELAY_MS = 200;

bool locked = false;
int stableReq = HIGH;
int lastReq = HIGH;
unsigned long reqEdge = 0;
unsigned long lastStatus = 0;
unsigned long engageCount = 0;
unsigned long doorOpenTime = 0;

void setLock(bool on)
{
    locked = on;
    digitalWrite(LOCK_PIN, on ? HIGH : LOW);
}

void publishStatus()
{
    Serial.print("vault lock=");
    Serial.print(locked ? 1 : 0);
    Serial.print(" engages=");
    Serial.println(engageCount);
}

bool doorClosed()
{
    return digitalRead(DOOR_PIN) == LOW;
}

void setup()
{
    pinMode(REQ_PIN, INPUT_PULLUP);
    pinMode(DOOR_PIN, INPUT_PULLUP);
    pinMode(LOCK_PIN, OUTPUT);
    setLock(false);
    Serial.begin(9600);
    stableReq = digitalRead(REQ_PIN);
    lastReq = stableReq;
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();
    int rawReq = digitalRead(REQ_PIN);
    int rawDoor = digitalRead(DOOR_PIN);

    // Debounce request button
    if (rawReq != lastReq)
    {
        reqEdge = now;
        lastReq = rawReq;
    }

    if ((now - reqEdge) >= DEBOUNCE_MS && rawReq != stableReq)
    {
        stableReq = rawReq;
        if (stableReq == LOW && doorClosed() && !locked)
        {
            setLock(true);
            engageCount++;
        }
    }

    // Debounce door closed sense
    static int stableDoor = HIGH;
    static unsigned long doorEdge = 0;
    if (rawDoor != stableDoor)
    {
        doorEdge = now;
        stableDoor = rawDoor;
    }

    if ((now - doorEdge) >= DEBOUNCE_MS && rawDoor != stableDoor)
    {
        stableDoor = rawDoor;
        if (!doorClosed())
        {
            doorOpenTime = now;
        }
    }

    // Unlock if door is opened and delay has passed
    if (!doorClosed() && (now - doorOpenTime >= UNLOCK_DELAY_MS))
    {
        setLock(false);
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        publishStatus();
    }
}

// Loft cooling fan with hysteresis and a boost button.
// TMP-style linear probe on A3 (10 mV/°C), fan on D5, boost on D4.

const int TEMP_PIN = A3;
const int FAN_PIN = 5;
const int BOOST_PIN = 4;

const float ON_C = 36.0f;
const float OFF_C = 32.0f;
const float MV_PER_C = 10.0f;
const unsigned long SAMPLE_MS = 50;
const unsigned long LOG_MS = 1000;
const unsigned long FAN_CHANGE_WINDOW_MS = 5000;
const int HOLD = 4;

bool fanOn = false;
int onHold = 0;
int offHold = 0;
unsigned long lastSample = 0;
unsigned long lastLog = 0;
unsigned long lastFanChange = 0;
float tempC = 0.0f;

float sampleTempC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void driveFan(bool on)
{
    fanOn = on;
    digitalWrite(FAN_PIN, on ? HIGH : LOW);
    lastFanChange = millis();
}

void logLine()
{
    Serial.print("loft: ");
    Serial.print(tempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    pinMode(BOOST_PIN, INPUT_PULLUP);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastSample = millis();
    lastLog = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        tempC = sampleTempC();

        if (digitalRead(BOOST_PIN) == LOW)
        {
            onHold = 0;
            offHold = 0;
            driveFan(true);
        }
        else
        {
            if (tempC >= ON_C)
            {
                onHold++;
            }
            else
            {
                onHold = 0;
            }
            if (tempC <= OFF_C)
            {
                offHold++;
            }
            else
            {
                offHold = 0;
            }

            if (onHold >= HOLD && fanOn == false && (now - lastFanChange) >= FAN_CHANGE_WINDOW_MS)
            {
                driveFan(true);
            }
            else if (offHold >= HOLD && fanOn == true && (now - lastFanChange) >= FAN_CHANGE_WINDOW_MS)
            {
                driveFan(false);
            }
        }
    }

    if (now - lastLog >= LOG_MS)
    {
        lastLog = now;
        logLine();
    }
}

